#!/usr/bin/env python3
"""The reader of the statusline readings (plan.md step 12).

It reads what the rig's recorder filed in the private directory and, when a home and an instance are given, the
home's `budget.json` and the instance's hook role file. It prints codes only: names, counts, JSON types and
equalities. No payload value, no prompt text and no path of the user's is printed; a number from the payload is
only ever compared, never shown.

  live-sl-read.py records <private dir> [<label>]           one line per recorder invocation, then a summary
  live-sl-read.py home <private dir> <home> <instance>      budget.json and the hook's role lines
  live-sl-read.py wait <private dir> <label> <what> <bound seconds>
        polls every 100 ms until a recorder invocation of <label> exists (`any`) or one whose payload holds
        `rate_limits` (`rate_limits`); prints how long it waited and what it settled on
  live-sl-read.py wait-home <private dir> <home> <instance> <what> <bound seconds>
        the same over the hook role file: `invoked` (a statusline hook-decision exists) or `written` (one with
        budget_written true)

Run from the repository root.
"""
import datetime
import glob
import json
import os
import sys
import time


def stamp():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z"


def json_type(value):
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "whole number"
    if isinstance(value, float):
        return "fraction"
    if isinstance(value, str):
        return "string"
    if value is None:
        return "null"
    return "array" if isinstance(value, list) else "object"


def window(value):
    if not isinstance(value, dict):
        return {"is": json_type(value)}
    used = value.get("used_percentage")
    return {
        "keys": sorted(value),
        "used_percentage": json_type(used) if "used_percentage" in value else "absent",
        "used_in_0_100": isinstance(used, (int, float)) and not isinstance(used, bool) and 0 <= used <= 100,
        "resets_at": json_type(value.get("resets_at")) if "resets_at" in value else "absent",
    }


def invocations(priv, label=None):
    out = []
    for meta in sorted(glob.glob(os.path.join(priv, "rec-*.meta"))):
        rec = {}
        with open(meta, encoding="utf-8") as f:
            for line in f:
                key, _, value = line.rstrip("\n").partition("=")
                rec[key] = value
        if label and rec.get("label") != label:
            continue
        try:
            with open(meta[: -len(".meta")] + ".stdin", "rb") as f:
                raw = f.read()
        except OSError:
            raw = None
        try:
            doc = json.loads(raw) if raw is not None else None
        except ValueError:
            doc = None
        rec["payload_object"] = isinstance(doc, dict)
        rec["_doc"] = doc if isinstance(doc, dict) else {}
        out.append(rec)
    return sorted(out, key=lambda r: r.get("at", ""))


def shown(rec):
    doc = rec["_doc"]
    limits = doc.get("rate_limits")
    line = {k: v for k, v in rec.items() if not k.startswith("_")}
    line["keys"] = sorted(doc)
    if isinstance(limits, dict):
        line["rate_limits"] = {name: window(value) for name, value in sorted(limits.items())}
    else:
        line["rate_limits"] = "absent" if "rate_limits" not in doc else json_type(limits)
    return line


def records(priv, label):
    recs = invocations(priv, label)
    for rec in recs:
        print(json.dumps(shown(rec), sort_keys=True))
    with_limits = [i for i, r in enumerate(recs) if isinstance(r["_doc"].get("rate_limits"), dict)]
    key_sets = sorted({tuple(sorted(r["_doc"])) for r in recs})
    summary = {
        "invocations": len(recs),
        "by_label": {},
        "with_rate_limits": len(with_limits),
        "first_with_rate_limits": with_limits[0] + 1 if with_limits else None,
        "distinct_key_sets": len(key_sets),
        "key_union": sorted({k for r in recs for k in r["_doc"]}),
        "launcher_arg0": sorted({r.get("launcher_arg0", "") for r in recs}),
        "launcher_bash": sorted({r.get("launcher_bash", "") for r in recs}),
        "launcher_zsh": sorted({r.get("launcher_zsh", "") for r in recs}),
        "ancestors": sorted(
            {" < ".join(r.get(f"p{n}_comm", "") + "(" + r.get(f"p{n}_exe", "") + ")" for n in (1, 2, 3)) for r in recs}
        ),
    }
    for r in recs:
        summary["by_label"][r.get("label")] = summary["by_label"].get(r.get("label"), 0) + 1
    print(json.dumps({"summary": summary}, sort_keys=True))


def role_lines(home, instance):
    path = os.path.join(home, "diagnostics", f"hook-{instance}.ndjson")
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        return []
    out = []
    for line in data[: data.rfind(b"\n") + 1].split(b"\n"):
        try:
            doc = json.loads(line)
        except ValueError:
            continue
        if isinstance(doc, dict):
            out.append(doc)
    return out


def statusline_lines(home, instance):
    lines = role_lines(home, instance)
    return [
        l for l in lines if l.get("hook_event") == "statusline" or l.get("subject") == "statusline-shell"
    ]


def rfc3339_of(seconds):
    at = datetime.datetime.fromtimestamp(seconds, datetime.timezone.utc)
    return at.strftime("%Y-%m-%dT%H:%M:%S.000Z")


def home(priv, home_dir, instance):
    lines = statusline_lines(home_dir, instance)
    counts = {}
    for l in lines:
        key = l.get("event", "")
        for field in ("subject", "detail", "budget_written", "shell_exit_status", "deadline_hit", "level"):
            if field in l:
                key += f" {field}={json.dumps(l[field])}"
        counts[key] = counts.get(key, 0) + 1
    durations = [l["duration_ms"] for l in lines if l.get("event") == "hook-decision" and "duration_ms" in l]
    shells = [l["duration_ms"] for l in lines if l.get("event") == "process-exit" and "duration_ms" in l]
    out = {
        "statusline_lines": len(lines),
        "by_shape": dict(sorted(counts.items())),
        "decision_ms": {"n": len(durations), "min": min(durations, default=None), "max": max(durations, default=None)},
        "shell_ms": {"n": len(shells), "min": min(shells, default=None), "max": max(shells, default=None)},
        "any_corr": any("corr" in l for l in lines),
        "field_names": sorted({k for l in lines for k in l}),
    }
    try:
        with open(os.path.join(home_dir, "budget.json"), encoding="utf-8") as f:
            budget = json.load(f)
    except (OSError, ValueError):
        budget = None
    if isinstance(budget, dict):
        forms = {}
        for name in ("five_hour", "seven_day"):
            w = budget.get(name)
            forms[name] = (
                {k: json_type(v) if v != "unknown" else "the word unknown" for k, v in sorted(w.items())}
                if isinstance(w, dict)
                else ("the word unknown" if w == "unknown" else json_type(w))
            )
        out["budget"] = {"keys": sorted(budget), "v": budget.get("v"), "windows": forms, "read_at_chars": len(str(budget.get("read_at", "")))}
        # the newest payload a wrapped recorder was handed that holds a reading, compared field by field
        wrapped = [r for r in invocations(priv, "wrapped") if isinstance(r["_doc"].get("rate_limits"), dict)]
        if wrapped:
            limits = wrapped[-1]["_doc"]["rate_limits"]
            same = {}
            for name in ("five_hour", "seven_day"):
                src, got = limits.get(name), budget.get(name)
                if not isinstance(src, dict):
                    same[name] = got == "unknown"
                    continue
                reset = src.get("resets_at")
                want_reset = rfc3339_of(reset) if isinstance(reset, int) and not isinstance(reset, bool) else None
                same[name] = (
                    isinstance(got, dict)
                    and got.get("used_percentage") == src.get("used_percentage")
                    and (want_reset is None or got.get("resets_at") == want_reset)
                )
            out["budget"]["equals_the_newest_wrapped_payload_s_reading"] = same
    else:
        out["budget"] = None
    try:
        mode = oct(os.stat(os.path.join(home_dir, "budget.json")).st_mode & 0o777)
    except OSError:
        mode = None
    out["budget_mode"] = mode
    print(json.dumps(out, sort_keys=True))


def wait(priv, label, what, bound, probe):
    began, began_at = time.monotonic(), stamp()
    while True:
        settled = probe()
        waited = time.monotonic() - began
        if settled is not None or waited >= bound:
            break
        time.sleep(0.1)
    doc = {
        "label": label,
        "what": what,
        "bound_s": bound,
        "began_at": began_at,
        "found": settled is not None,
        "waited_s": round(waited, 3),
        "settled_on": settled,
    }
    line = json.dumps(doc, sort_keys=True)
    with open(os.path.join(priv, "waits.ndjson"), "a", encoding="utf-8") as f:
        f.write(line + "\n")
    print(line)


def main():
    args = sys.argv[1:]
    if len(args) >= 2 and args[0] == "records":
        records(args[1], args[2] if len(args) > 2 else None)
    elif len(args) == 4 and args[0] == "home":
        home(args[1], args[2], args[3])
    elif len(args) == 5 and args[0] == "wait":
        priv, label, what, bound = args[1], args[2], args[3], float(args[4])

        def probe():
            recs = invocations(priv, label)
            if what == "rate_limits":
                recs = [r for r in recs if isinstance(r["_doc"].get("rate_limits"), dict)]
            return {"invocations": len(recs), "first_at": recs[0].get("at")} if recs else None

        wait(priv, label, what, bound, probe)
    elif len(args) == 6 and args[0] == "wait-home":
        priv, home_dir, instance, what, bound = args[1], args[2], args[3], args[4], float(args[5])

        def probe():
            lines = [l for l in statusline_lines(home_dir, instance) if l.get("event") == "hook-decision"]
            if what == "written":
                lines = [l for l in lines if l.get("budget_written") is True]
            return {"decisions": len(lines), "first_at": lines[0].get("timestamp")} if lines else None

        wait(priv, instance, what, bound, probe)
    else:
        sys.exit(__doc__)


if __name__ == "__main__":
    main()

#!/usr/bin/env bash
# The launcher of one statusline session on the headless pty host (plan.md step 12). It holds the prompt, so no
# quoted text crosses a command line, and it passes no --settings of its own: under `wrapped` the only --settings
# the CLI gets is the override viola writes.
#   live-sl-start.sh <private dir> <label> unwrapped <dir>
#   live-sl-start.sh <private dir> <label> wrapped   <dir> <home> <instance>
#   live-sl-start.sh <private dir> <label> rehearsal <dir> <home> <instance> [stdin]
# <dir> and <home> are relative to the repository root. `unwrapped` and `wrapped` start claude 2.1.287, named by
# path, with its install directory first on PATH, on the model alias haiku, with one short prompt as its
# argument. `rehearsal` starts the harness build's fake agent under the product build instead (no live start);
# with `stdin` it hands the fake agent the rig's synthetic statusline payload.
set -eu
ROOT=$(git -C "$(dirname "$0")" rev-parse --show-toplevel)
HERE=$(cd "$(dirname "$0")" && pwd)
PRIV=${1:?usage: live-sl-start.sh <private dir> <label> <mode> <dir> ...}
LABEL=${2:?label}
MODE=${3:?mode}
DIR=${4:?dir}
case "$DIR" in
  target/sl-live-*/a | target/sl-live-*/b) ;;
  *) echo "live-sl-start: the directory is not target/sl-live-*/a or /b" >&2; exit 2 ;;
esac
[ -d "$ROOT/$DIR" ] || { echo "live-sl-start: no such directory" >&2; exit 2; }
CLI_DIR=$HOME/.local/share/mise/installs/claude/2.1.287
CLI=$CLI_DIR/claude
VIOLA=$ROOT/target/release-check/release/viola
PROMPT='Reply with the single word READY and nothing else.'
home_of() {
  case "$1" in
    target/e2e-home/viola-live-sl-*/home) ;;
    *) echo "live-sl-start: the home is not a viola-live-sl home under target/e2e-home/" >&2; exit 2 ;;
  esac
  printf '%s' "$ROOT/$1"
}
cd "$ROOT/$DIR"
export PATH="$CLI_DIR:$PATH"
case "$MODE" in
  unwrapped)
    exec python3 "$HERE/live-pty.py" "$PRIV" "$LABEL" -- "$CLI" --model haiku "$PROMPT"
    ;;
  wrapped)
    H=$(home_of "${5:?home}")
    exec python3 "$HERE/live-pty.py" "$PRIV" "$LABEL" -- "$VIOLA" --home "$H" run "${6:?instance}" -- \
      "$CLI" --model haiku "$PROMPT"
    ;;
  rehearsal)
    H=$(home_of "${5:?home}")
    FAKE=$ROOT/target/harness/debug/viola-fake-agent
    set -- "$VIOLA" --home "$H" run "${6:?instance}" -- "$FAKE" --receipt "$PRIV/$LABEL.receipt.ndjson" ${7:+--statusline-stdin "$PRIV/rehearsal.stdin"}
    exec python3 "$HERE/live-pty.py" "$PRIV" "$LABEL" -- "$@"
    ;;
  *)
    echo "live-sl-start: unknown mode" >&2
    exit 2
    ;;
esac

#!/usr/bin/env python3
"""The driver of the live sessions (plan.md steps 6 to 9).

It runs the product's own verbs, `target/release-check/release/viola --home <home> <verb> <name>`, with the text
on stdin and stdout / stderr in files of a private directory outside the tree, and keeps a journal of codes:
verb, exit, times, the byte size of the instance's event log before and after, a cursor, a dialog id and kind,
the rule a dialog was answered by. No prompt text, assistant text or event payload text is printed or journalled.

A dialog must be answered by its id inside the wrapper's 60 s deadline, so a turn is one call: send, wait, answer
each dialog as it is raised, wait again, until the turn ends.

  live-drive.py <private dir> <home> <name> send <label> <text file>
  live-drive.py <private dir> <home> <name> turn <label> <text file> [--timeout-ms N]
        [--question <asked text> <answer>] [--deny-true] [--plan approve]
        [--then <label> <text file>]
  live-drive.py <private dir> <home> <name> last <label> [<expected single word>]
  live-drive.py selftest

Run from the repository root.
"""
import datetime
import json
import os
import re
import subprocess
import sys

VIOLA = "target/release-check/release/viola"
HOME = os.path.expanduser("~")
SKILLS = HOME + "/.claude/skills/"
DENY = {"behavior": "deny", "message": "not part of this test"}
DIALOG_KINDS = ("question", "permission", "plan")
GIT_READS = ("status", "log", "rev-list", "rev-parse", "diff", "show", "ls-files")


def stamp():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z"


class Drive:
    def __init__(self, priv, home, name):
        self.priv = priv
        self.home = home
        self.name = name
        self.events = os.path.join(home, "instances", name, "events.ndjson")
        self.journal = os.path.join(priv, "journal.ndjson")

    def size(self):
        try:
            return os.path.getsize(self.events)
        except OSError:
            return 0

    def count(self):
        try:
            with open(self.journal, encoding="utf-8") as f:
                return sum(1 for _ in f)
        except OSError:
            return 0

    def note(self, rec):
        with open(self.journal, "a", encoding="utf-8") as f:
            f.write(json.dumps(rec, sort_keys=True) + "\n")

    def verb(self, label, verb, args, stdin):
        n = self.count() + 1
        base = "%03d-%s-%s" % (n, label, verb)
        out = os.path.join(self.priv, base + ".out")
        err = os.path.join(self.priv, base + ".err")
        before = self.size()
        t0 = stamp()
        with open(out, "wb") as o, open(err, "wb") as e:
            p = subprocess.run(
                [VIOLA, "--home", self.home, verb, self.name, *args],
                input=stdin if stdin is not None else b"",
                stdout=o,
                stderr=e,
                check=False,
            )
        rec = {
            "n": n,
            "label": label,
            "verb": verb,
            "args": [a for a in args],
            "exit": p.returncode,
            "t0": t0,
            "t1": stamp(),
            "events_before": before,
            "events_after": self.size(),
            "out": base + ".out",
            "err": base + ".err",
            "stdin_bytes": len(stdin) if stdin is not None else 0,
        }
        return rec, out, err


def expand(token, variables):
    t = token.strip("\"'")
    t = t.replace("${HOME}", HOME).replace("$HOME", HOME)
    if t == "~" or t.startswith("~/"):
        t = HOME + t[1:]
    for k, v in variables.items():
        t = t.replace("${%s}" % k, v).replace("$%s" % k, v)
    if "$" in t or "~" in t:
        return None
    return os.path.normpath(t)


def bash_is_safe(cmd, root):
    """A Bash call allowed without a human: the skills' own tool scripts, a git read, an echo, a cd to the root."""
    if any(x in cmd for x in ("`", "$(", "<", "\\")):
        return False
    c = cmd.replace("2>/dev/null", " ").replace("2>&1", " ")
    if ">" in c:
        return False
    segs = re.split(r";|&&|\|\||\n", c)
    if any("|" in s or "&" in s for s in segs):
        return False
    variables = {}
    seen = 0
    for seg in segs:
        s = seg.strip()
        if not s:
            continue
        seen += 1
        m = re.fullmatch(r"([A-Za-z_][A-Za-z0-9_]*)=(\S+)", s)
        if m:
            p = expand(m.group(2), variables)
            if p and (p + "/").startswith(SKILLS):
                variables[m.group(1)] = p
                continue
            return False
        toks = s.split()
        head = toks[0]
        if head == "true" and seen > 1 and len(toks) == 1:
            continue
        if head == "cd":
            if len(toks) == 2 and expand(toks[1], variables) == root:
                continue
            return False
        if head == "echo":
            rest = s[4:].replace("$?", "")
            if "$" in rest:
                return False
            continue
        if head == "git":
            if len(toks) >= 2 and toks[1] == "branch" and toks[2:] == ["--show-current"]:
                continue
            if len(toks) >= 2 and toks[1] in GIT_READS:
                if any(t.startswith("--output") or t.startswith("--ext-diff") or t == "-o" for t in toks[2:]):
                    return False
                if "$" in s:
                    return False
                continue
            return False
        if head in ("python", "python3") and toks[1:3] == ["-X", "utf8"] and len(toks) >= 4:
            p = expand(toks[3], variables)
            if not (p and p.startswith(SKILLS) and p.endswith(".py")):
                return False
            for t in toks[4:]:
                if "$" in t and expand(t, variables) is None:
                    return False
            continue
        return False
    return seen > 0


def decide(kind, data, planned, root):
    """The response to a raised dialog and the rule it came from. None: no answer here, control returns."""
    if kind == "question" and "question" in planned:
        asked, answer = planned.pop("question")
        qs = data.get("questions") or []
        text = qs[0].get("question") if qs and isinstance(qs[0], dict) else None
        if not isinstance(text, str):
            return None, "question-unreadable", {}
        return {"answers": {text: answer}}, "planned", {"asked_as_planned": text == asked, "questions": len(qs)}
    if kind == "permission":
        tool = data.get("tool")
        inp = data.get("input") if isinstance(data.get("input"), dict) else {}
        cmd = inp.get("command") if isinstance(inp.get("command"), str) else ""
        extra = {"tool": tool if isinstance(tool, str) else None}
        if planned.get("deny-true") and tool == "Bash" and cmd.strip() == "true":
            planned.pop("deny-true")
            return dict(DENY), "planned", dict(extra, behavior="deny", command_is_true=True)
        if tool in ("Read", "Glob", "Grep"):
            return {"behavior": "allow"}, "auto-read-tool", dict(extra, behavior="allow")
        if tool == "Bash" and bash_is_safe(cmd, root):
            return {"behavior": "allow"}, "auto-skill-script-or-read", dict(extra, behavior="allow")
        return dict(DENY), "auto-deny", dict(extra, behavior="deny")
    if kind == "plan" and "plan" in planned:
        behavior = planned.pop("plan")
        return {"behavior": behavior}, "planned", {"behavior": behavior}
    if kind == "question":
        qs = data.get("questions") or []
        answers = {q.get("question"): "Not now, thank you." for q in qs if isinstance(q, dict) and isinstance(q.get("question"), str)}
        if not answers:
            return None, "question-unreadable", {}
        return {"answers": answers}, "auto-decline", {"questions": len(qs)}
    return None, "unplanned-" + kind, {}


def do_send(d, label, path):
    with open(path, "rb") as f:
        text = f.read()
    rec, out, err = d.verb(label, "send", [], text)
    with open(out, "rb") as f:
        first = f.read()
    m = re.search(rb"^\[RB\] read back\s+\S+\s+\S+\s+cursor (\d+)", first)
    if m:
        rec["result"] = "read-back"
        rec["cursor"] = int(m.group(1))
    elif first.startswith(b"[  ] unconfirmable"):
        rec["result"] = "unconfirmable"
    else:
        rec["result"] = "none"
    with open(err, "rb") as f:
        words = f.read().decode("utf-8", "replace").split("\n")
    # a refusal's mirror line holds codes only: the box, `unable`, the name, the reason and its detail
    rec["stderr_codes"] = [w.split() for w in words if w.startswith("[/ ]")][:1]
    rec["stderr_hint_lines"] = sum(1 for w in words if w.startswith("hint: "))
    rec["hint_names_release"] = any("release" in w for w in words if w.startswith("hint: "))
    d.note(rec)
    return rec


def wait_loop(d, label, cursor, timeout_ms, planned, root):
    answered = []
    while True:
        rec, out, _ = d.verb(label, "wait", ["--after", str(cursor), "--timeout-ms", str(timeout_ms), "--json"], None)
        try:
            with open(out, encoding="utf-8") as f:
                ok = json.load(f).get("ok") or {}
        except (OSError, ValueError):
            ok = {}
        if rec["exit"] != 0 or not ok:
            rec["woke"] = "no-document"
            d.note(rec)
            return "no-document", cursor, answered
        if ok.get("timed_out") is True:
            rec["woke"] = "timed-out"
            d.note(rec)
            return "timed-out", cursor, answered
        event = ok.get("event") or {}
        kind = event.get("kind")
        cursor = ok.get("cursor", cursor)
        rec["woke"] = kind
        rec["cursor"] = cursor
        rec["event_ts"] = event.get("ts")
        data = event.get("data") if isinstance(event.get("data"), dict) else {}
        if kind in DIALOG_KINDS:
            rec["dialog_id"] = data.get("dialog_id")
            d.note(rec)
            response, rule, extra = decide(kind, data, planned, root)
            if response is None:
                d.note({"n": d.count() + 1, "label": label, "verb": "none", "dialog_id": data.get("dialog_id"), "kind": kind, "rule": rule, "t0": stamp()})
                return "dialog-unanswered:" + kind + ":" + str(data.get("dialog_id")), cursor, answered
            arec, _, _ = d.verb(label, "answer", [str(data.get("dialog_id"))], json.dumps(response).encode())
            arec.update({"dialog_id": data.get("dialog_id"), "kind": kind, "rule": rule})
            arec.update(extra)
            d.note(arec)
            answered.append({"dialog_id": data.get("dialog_id"), "kind": kind, "rule": rule, "answer_exit": arec["exit"]})
            continue
        d.note(rec)
        return kind, cursor, answered


def op_turn(d, argv):
    label, path = argv[0], argv[1]
    rest = argv[2:]
    timeout_ms = 900000
    planned = {}
    then = None
    i = 0
    while i < len(rest):
        if rest[i] == "--timeout-ms":
            timeout_ms = int(rest[i + 1]); i += 2
        elif rest[i] == "--question":
            planned["question"] = (rest[i + 1], rest[i + 2]); i += 3
        elif rest[i] == "--deny-true":
            planned["deny-true"] = True; i += 1
        elif rest[i] == "--plan":
            planned["plan"] = rest[i + 1]; i += 2
        elif rest[i] == "--then":
            then = (rest[i + 1], rest[i + 2]); i += 3
        else:
            sys.exit("usage: unknown option " + rest[i])
    root = os.getcwd()
    s = do_send(d, label, path)
    summary = {"label": label, "send_exit": s["exit"], "send_result": s["result"], "cursor": s.get("cursor"), "stderr_codes": s["stderr_codes"]}
    if s["exit"] == 0 and "cursor" in s:
        woke, cursor, answered = wait_loop(d, label, s["cursor"], timeout_ms, planned, root)
        summary.update({"woke": woke, "end_cursor": cursor, "dialogs": answered, "planned_left": sorted(planned.keys())})
        if then and woke == "turn-ended":
            s2 = do_send(d, then[0], then[1])
            second = {"label": then[0], "send_exit": s2["exit"], "send_result": s2["result"], "cursor": s2.get("cursor"), "stderr_codes": s2["stderr_codes"]}
            if s2["exit"] == 0 and "cursor" in s2:
                woke2, cursor2, answered2 = wait_loop(d, then[0], s2["cursor"], timeout_ms, {}, root)
                second.update({"woke": woke2, "end_cursor": cursor2, "dialogs": answered2})
            summary["then"] = second
    print(json.dumps(summary, sort_keys=True))


def op_send(d, argv):
    s = do_send(d, argv[0], argv[1])
    print(json.dumps({k: s.get(k) for k in ("label", "exit", "result", "cursor", "stderr_codes", "stderr_hint_lines", "hint_names_release", "events_before", "events_after")}, sort_keys=True))


def op_last(d, argv):
    label = argv[0]
    word = argv[1] if len(argv) > 1 else None
    rec, out, _ = d.verb(label, "last", [], None)
    with open(out, "rb") as f:
        text = f.read().decode("utf-8", "replace")
    stripped = text.strip()
    rec["text_bytes"] = len(text.encode("utf-8"))
    rec["non_empty"] = bool(stripped)
    rec["holds_closing_question"] = "Ready to continue?" in text
    rec["words"] = len(stripped.split())
    if word is not None:
        rec["is_the_word"] = stripped.strip(".!\"'` ").lower() == word.lower()
    d.note(rec)
    print(json.dumps({k: rec.get(k) for k in ("label", "exit", "text_bytes", "non_empty", "holds_closing_question", "words", "is_the_word")}, sort_keys=True))


def selftest():
    root = os.getcwd()
    t = SKILLS + "andromeda-new-session/../andromeda-tools/scripts"
    cases = [
        ("python -X utf8 %s/health.py check --root . --stack rust --style agent-driven" % t, True),
        ("T=%s; python -X utf8 $T/route.py cursor --root .; echo \"=== exit $?\"" % t, True),
        ("cd %s; git status --short; git log --oneline -10" % root, True),
        ("git branch --show-current; echo ---; git rev-list --count @{u}..HEAD 2>/dev/null || true", True),
        ("true", False),
        ("git branch -D x", False),
        ("python -X utf8 /usr/lib/x.py", False),
        ("python -X utf8 %s/evolve.py append --root . --count 1 --records-file - <<'NDJSON'\n{}\nNDJSON" % t, False),
        ("git status > out.txt", False),
        ("git log | head", False),
        ("rm -rf x", False),
        ("cd /; git status", False),
        ("echo $(id)", False),
        ("python -X utf8 %s/../../../../x.py" % t, False),
    ]
    bad = 0
    for cmd, want in cases:
        got = bash_is_safe(cmd, root)
        if got != want:
            bad += 1
            print("MISMATCH want %s got %s: case %d" % (want, got, cases.index((cmd, want))))
    r, rule, _ = decide("permission", {"tool": "Bash", "input": {"command": "true"}}, {"deny-true": True}, root)
    if not (r == DENY and rule == "planned"):
        bad += 1
        print("MISMATCH the planned deny")
    r, rule, _ = decide("permission", {"tool": "Write", "input": {}}, {}, root)
    if not (r == DENY and rule == "auto-deny"):
        bad += 1
        print("MISMATCH a write tool")
    r, rule, x = decide("question", {"questions": [{"question": "Which colour?", "options": ["red", "blue"]}]}, {"question": ("Which colour?", "blue")}, root)
    if not (r == {"answers": {"Which colour?": "blue"}} and x.get("asked_as_planned") is True):
        bad += 1
        print("MISMATCH the planned question")
    r, rule, _ = decide("plan", {"plan": "x"}, {}, root)
    if r is not None:
        bad += 1
        print("MISMATCH an unplanned plan")
    print("selftest: %d cases, %d mismatches" % (len(cases) + 4, bad))
    sys.exit(1 if bad else 0)


def main():
    if len(sys.argv) == 2 and sys.argv[1] == "selftest":
        selftest()
    if len(sys.argv) < 6:
        sys.exit(__doc__)
    priv, home, name, op = sys.argv[1:5]
    if not os.path.isdir(priv):
        sys.exit("no private directory")
    d = Drive(priv, home, name)
    if op == "send":
        op_send(d, sys.argv[5:])
    elif op == "turn":
        op_turn(d, sys.argv[5:])
    elif op == "last":
        op_last(d, sys.argv[5:])
    else:
        sys.exit(__doc__)


if __name__ == "__main__":
    main()

